 void InvalidateChecks(){CheckContext="";SiteStatus="Сайты: требуется повторная проверка";}
 void RecordChecks(ProbeResult[] results){CheckContext=RuntimeContext();SiteStatus="Сайты: "+results.Count(x=>x.Ok)+"/"+results.Length+" доступны · "+DateTime.Now.ToString("HH:mm");if(B.Running)SaveStrategyResult(B.ActiveStrategy,results);B.Pref["last-check-time"]=DateTime.Now.ToString("yyyy-MM-dd HH:mm");B.SavePrefs();}
 void SaveStrategyResult(string strategy,ProbeResult[] results){if(!B.Strategies.Contains(strategy))return;B.Pref["result."+strategy]=DateTime.Now.ToString("yyyy-MM-dd HH:mm")+" · "+results.Count(x=>x.Ok)+"/"+results.Length+" HTTPS";B.SavePrefs();}
 void RefreshComfort(){if(HomeStrategy!=null&&!HomeStrategy.IsDisposed)HomeStrategy.Text=Path.GetFileNameWithoutExtension(Selected)+" · "+B.Strategies.Length+" вариантов в сборке";bool running=B.Running||B.ServiceState()==4;if(WasRunning.HasValue&&WasRunning.Value!=running){if(running){SidebarPet.React();if(HeroBox!=null)HeroBox.Pet.React();}else{SidebarPet.Rest();if(HeroBox!=null)HeroBox.Pet.Rest();}}WasRunning=running;if(CheckContext.Length>0&&CheckContext!=RuntimeContext())InvalidateChecks();if(ConnectionLabel!=null&&!ConnectionLabel.IsDisposed)ConnectionLabel.Text=SiteStatus+"\nГолос и видео: требуется ручная проверка";if(MiniStatus!=null&&!MiniStatus.IsDisposed)MiniStatus.Text=(running?"Движок запущен":"Движок остановлен")+"\n"+System.IO.Path.GetFileNameWithoutExtension(Selected)+"\n"+SiteStatus;if(MiniPet!=null&&!MiniPet.IsDisposed){MiniPet.Sleeping=!running;MiniPet.Checking=Scanning;MiniPet.Reduced=!Motion.Enabled;MiniPet.Advance(Motion.Now);}}
 void ApplyPetSettings(){string mode=B.Get("pet","normal");foreach(var pet in new[]{SidebarPet,HeroBox==null?null:HeroBox.Pet,MiniPet})if(pet!=null&&!pet.IsDisposed){pet.Visible=mode!="hidden";pet.Calm=B.Get("pet-calm","yes")=="yes";pet.SpriteScale=mode=="small"?.72f:1;}}
 void ComfortSettings(){var c=Box(1150,174);Title(c,"Твой дракон","Спокойное ожидание и размер персонажа.");var size=Combo(c,new[]{"Обычный","Маленький","Скрыть"},23,103,230);string[] values={"normal","small","hidden"};size.SelectedIndex=Math.Max(0,Array.IndexOf(values,B.Get("pet","normal")));size.SelectedIndexChanged+=(s,e)=>{B.Pref["pet"]=values[size.SelectedIndex];B.SavePrefs();ApplyPetSettings();};Check(c,"Спокойные реакции без прыжков",285,107,B.Get("pet-calm","yes")=="yes",v=>{B.Pref["pet-calm"]=v?"yes":"no";B.SavePrefs();ApplyPetSettings();});}
 void StrategyExtras(FList list,Action fill){var c=Box(515,226);Title(c,"Твои отметки","Избранные сверху. Затем — недавно выбранные. Проверки привязаны ко времени.");var meta=L(c,"",23,85,710,28,10);var note=Input(c,"",23,122,440);var favorite=Btn(c,"В избранное",478,122,224,35,()=>{if(list.SelectedItem==null)return;string key="favorite."+list.SelectedItem;B.Pref[key]=B.Get(key)=="yes"?"no":"yes";B.SavePrefs();fill();});Btn(c,"Сохранить заметку",23,173,245,35,()=>{if(list.SelectedItem==null)return;B.Pref["note."+list.SelectedItem]=Convert.ToBase64String(Encoding.UTF8.GetBytes(note.Text));B.SavePrefs();Feedback("Заметка сохранена",list.SelectedItem.ToString());});Action refresh=()=>{if(list.SelectedItem==null)return;string strategy=list.SelectedItem.ToString();favorite.Text=B.Get("favorite."+strategy)=="yes"?"★ В избранном":"☆ В избранное";try{note.Text=Encoding.UTF8.GetString(Convert.FromBase64String(B.Get("note."+strategy)));}catch{note.Text="";}meta.Text=B.Get("result."+strategy,"Для этой стратегии нет результатов проверки");};list.SelectedIndexChanged+=(s,e)=>refresh();refresh();}
 void RestoreWorking(){string path=B.Working();if(path==null)throw new Exception("Сначала отметь рабочую конфигурацию в разделе «Профили».");string strategy=File.ReadAllText(Path.Combine(path,"strategy.txt"));if(Confirm("Вернуть "+strategy+"?\n"+B.Description(path)+"\nПоследняя проверка: "+B.Get("result."+strategy,"нет отметки")+"\nТекущая конфигурация будет сохранена в истории."))Work(()=>B.ApplySnapshot(path),SyncProfile);}
