 void ShowMini(){if(Mini!=null&&!Mini.IsDisposed){Mini.Show();Mini.Activate();Hide();return;}Mini=new Form{Text="FurZap · компактный",ClientSize=new Size(520,245),MinimumSize=new Size(536,284),BackColor=Theme.Bg,ForeColor=Theme.Text,StartPosition=FormStartPosition.CenterScreen,Icon=Icon};MiniStatus=L(Mini,"",22,20,350,83,11,true);MiniPet=new Dragon{Bounds=new Rectangle(375,14,122,117),Calm=true};Mini.Controls.Add(MiniPet);Btn(Mini,"Запустить",22,122,150,40,()=>Work(()=>{if(B.ServiceState()!=0)B.ServiceStart();else B.Start(Selected);}));Btn(Mini,"Остановить",184,122,150,40,()=>Work(()=>{B.Stop();if(B.ServiceState()!=0)B.ServiceStop();}));Btn(Mini,"Полный интерфейс",22,182,312,40,()=>{Mini.Hide();Restore();});double nextMiniRefresh=0;var timer=new System.Windows.Forms.Timer{Interval=17};timer.Tick+=(s,e)=>{if(Mini.Visible&&Mini.WindowState!=FormWindowState.Minimized){MiniPet.Advance(Motion.Now);if(Motion.Now>=nextMiniRefresh){nextMiniRefresh=Motion.Now+2;RefreshComfort();}}};Mini.Shown+=(s,e)=>timer.Start();Mini.FormClosing+=(s,e)=>{timer.Dispose();Restore();};Mini.Disposed+=(s,e)=>timer.Dispose();RefreshComfort();ApplyPetSettings();Mini.Show();Hide();}
 public static string RedactReport(string text,string user,string root){foreach(string value in new[]{root,Environment.GetFolderPath(Environment.SpecialFolder.UserProfile)})if(!String.IsNullOrEmpty(value))text=text.Replace(value,"[папка]");if(!String.IsNullOrEmpty(user))text=text.Replace(user,"[пользователь]");text=Regex.Replace(text,@"(?i)(authorization|token|password|secret|api[_-]?key)\s*[:=]\s*\S+","$1=[скрыто]");text=Regex.Replace(text,@"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}","[email]");text=Regex.Replace(text,@"\b(?:\d{1,3}\.){3}\d{1,3}\b","[IP]");text=Regex.Replace(text,@"(?i)\b[0-9a-f]{0,4}:(?:[0-9a-f:]+:)[0-9a-f:]*\b","[IPv6]");text=Regex.Replace(text,@"https?://[^\s]+","[URL]");return text;}
 void ShowErrorReport(){string report="FurZap "+typeof(MainForm).Assembly.GetName().Version+"\nWindows/runtime: "+Environment.OSVersion+" / "+Environment.Version+"\nРаздел: "+Subtitle.Text+"\nСтратегия: "+Selected+"\n\nПоследняя ошибка:\n"+LastException+"\n\nСобытия:\n"+Journal;report=RedactReport(report,Environment.UserName,Path.GetFullPath(B.Root));TextDialog("Отчёт — проверь и удали личные данные перед сохранением",report,true,value=>{using(var dialog=new SaveFileDialog{FileName="FurZap-report.txt",Filter="Текст|*.txt"})if(dialog.ShowDialog(this)==DialogResult.OK)File.WriteAllText(dialog.FileName,value,Encoding.UTF8);});}
 void UpdateCard(){var c=Box(785,148);Title(c,"Обновления FurZap","Новая версия, список изменений и проверка SHA-256 перед установкой.");Btn(c,"Проверить FurZap",23,93,260,36,CheckAppUpdate,true);Btn(c,"Отчёт об ошибке",298,93,240,36,ShowErrorReport);}
 async void CheckAppUpdate(){if(Busy||B.Preview)return;Busy=true;var updateButton=ActionButton;string updateText=updateButton==null?null:updateButton.Text;if(updateButton!=null)updateButton.Text="Проверяю…";try{var release=await Task.Run(()=>AppUpdater.Latest());if(release.Version<=typeof(MainForm).Assembly.GetName().Version){Feedback("Обновлений нет","Установлена актуальная версия.");return;}if(!Confirm("Доступна версия "+release.Version+"\n\n"+release.Notes+"\n\nСкачать обновление?"))return;using(var dialog=new Form{Text="Загрузка FurZap",ClientSize=new Size(440,160),StartPosition=FormStartPosition.CenterParent,BackColor=Theme.Bg})using(var cancel=new CancellationTokenSource()){var bar=new ProgressBar{Bounds=new Rectangle(24,28,390,25)};dialog.Controls.Add(bar);var label=L(dialog,"Загрузка…",24,62,390,25);var abort=new FButton{Text="Отменить",Bounds=new Rectangle(24,102,180,36)};abort.Click+=(s,e)=>cancel.Cancel();dialog.Controls.Add(abort);dialog.FormClosing+=(s,e)=>cancel.Cancel();dialog.Show(this);string staged=await Task.Run(()=>AppUpdater.Download(release,B.Data,cancel.Token,percent=>UI(()=>{if(!dialog.IsDisposed){bar.Value=percent;label.Text=percent+"%";}})));dialog.Close();if(!Confirm("Архив проверен. Установить FurZap "+release.Version+" и перезапустить приложение?\nОбычный процесс FurZap будет остановлен. Служба продолжит работать. Настройки и списки сохранятся."))return;if(HasUnsavedLists()){MessageBox.Show(this,"Сначала сохрани список и повтори обновление.");return;}B.Stop();AppUpdater.LaunchInstaller(staged);Busy=false;AllowExit=true;Close();}}catch(OperationCanceledException){Feedback("Загрузка отменена","Приложение не изменено.");}catch(Exception ex){Error(ex);}finally{Busy=false;if(updateButton!=null&&!updateButton.IsDisposed)updateButton.Text=updateText;}}
